window.HOEREN_TESTS[93] = {"id":"an-der-tankstelle","name":"An der Tankstelle","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: An unserer Tankstelle ist der Diesel diese Woche im Angebot, fünf Cent günstiger pro Liter. Benzin bleibt leider beim normalen Preis, es ist also nicht beides günstiger. Außerdem gibt es beim Tanken ab vierzig Litern einen kostenlosen Kaffee. Nutzen Sie das Angebot, es gilt nur bis Sonntag. Gute Fahrt!","gender":"f","q":"Was ist diese Woche günstiger?","opts":["Diesel.","Benzin.","Beides."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Ich stehe an der Tankstelle und mein Auto springt nicht mehr an. Ich glaube, die Batterie ist leer. Kannst du mit deinem Auto kommen und mir Starthilfe geben? Ich bin an der Tankstelle bei der Autobahn. Bitte beeil dich, ich muss zur Arbeit!","gender":"m","q":"Was ist Markus' Problem?","opts":["Der Tank ist leer.","Ein Reifen ist platt.","Die Batterie ist leer."],"correct":2},{"transcript":"Achtung Kunden: Unsere Tankstelle hat jetzt rund um die Uhr geöffnet. Nachts bezahlen Sie aber nur am Automaten, nicht im Shop. Der Shop mit Snacks und Getränken ist von 6 bis 22 Uhr offen. Auch die Waschanlage läuft nur tagsüber. Wir freuen uns, dass Sie immer tanken können!","gender":"m","q":"Wie zahlt man nachts?","opts":["Am Automaten.","Im Shop.","Mit Bargeld beim Personal."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Hör mal, ich war an der Tankstelle und habe gleich das Auto waschen lassen, in der Waschanlage. Sieht aus wie neu! Es gibt verschiedene Programme, ich habe das mit Wachs genommen. Kostet nur acht Euro. Dein Auto ist doch auch so schmutzig. Mach das mal, lohnt sich!","gender":"f","q":"Was hat Anna an der Tankstelle gemacht?","opts":["Einen Reifen gewechselt.","Das Auto gewaschen.","Nur getankt."],"correct":1},{"transcript":"Liebe Kunden: Bitte rauchen Sie an der Tankstelle nicht, auch nicht in der Nähe der Zapfsäulen. Benutzen Sie während des Tankens auch nicht Ihr Handy. Beides ist gefährlich. Schalten Sie den Motor aus, bevor Sie tanken. Wir bitten um Ihre Sicherheit und die aller anderen. Vielen Dank!","gender":"f","q":"Was soll man beim Tanken nicht tun?","opts":["Den Motor ausschalten.","Bezahlen.","Rauchen und das Handy benutzen."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Wir halten nur kurz. Der Wagen ist fast leer. Wer macht heute was?"},{"speaker":"Lisa","gender":"f","text":"Ich habe ein paar Minuten. Sag mir zuerst deinen Plan."},{"speaker":"Lukas","gender":"m","text":"Ich will nur tanken. Danach fahre ich gleich weiter zur Arbeit."},{"speaker":"Lisa","gender":"f","text":"Dann stell dich links hin. Putzt jemand noch die Scheiben?"},{"speaker":"Lukas","gender":"m","text":"Die Scheiben putzen wir nicht. Dazu ist keine Zeit."},{"speaker":"Lisa","gender":"f","text":"Ich lasse das Auto waschen, weil der Regen es schmutzig gemacht hat."},{"speaker":"Lukas","gender":"m","text":"Das dauert ein bisschen. Tom ist schon bei den Reifen."},{"speaker":"Lisa","gender":"f","text":"Tom will den Reifendruck prüfen. Ein Reifen sieht ihm zu weich aus."},{"speaker":"Lukas","gender":"m","text":"Macht jemand Staubsaugen im Wagen? Der Boden ist schmutzig."},{"speaker":"Lisa","gender":"f","text":"Staubsaugen macht heute keiner."},{"speaker":"Lukas","gender":"m","text":"Sara will noch etwas zu essen holen."},{"speaker":"Lisa","gender":"f","text":"Sara will im Shop einkaufen. Sie braucht Brot und Käse für die Fahrt."},{"speaker":"Lukas","gender":"m","text":"Der kleine Laden ist noch offen. Tim steht schon an der Seite."},{"speaker":"Lisa","gender":"f","text":"Tim muss Luft und Wasser nachfüllen. Das dauert nur eine Minute."},{"speaker":"Lukas","gender":"m","text":"Das geht schnell."},{"speaker":"Lisa","gender":"f","text":"Wir fahren gleich weiter."}],"options":[{"letter":"a","text":"Scheiben putzen"},{"letter":"b","text":"Öl nachfüllen"},{"letter":"c","text":"Im Shop einkaufen"},{"letter":"d","text":"Auto waschen"},{"letter":"e","text":"Luft und Wasser nachfüllen"},{"letter":"f","text":"Nur tanken"},{"letter":"g","text":"Eine Karte kaufen"},{"letter":"h","text":"Staubsaugen"},{"letter":"i","text":"Reifendruck prüfen"}],"items":[{"person":"Lukas","correct":"f"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"i"},{"person":"Sara","correct":"c"},{"person":"Tim","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Entschuldigung, welche Säule war das gerade? Nummer 2, Nummer 4 oder Nummer 6?"},{"speaker":"Kassierer","gender":"m","text":"Welche Nummer steht da an der Säule? 2, 4 oder 6, das muss auf dem Display stehen."},{"speaker":"Kunde","gender":"m","text":"Ah, Nummer 4. Nicht 2 und nicht 6, ich habe nachgeschaut."},{"speaker":"Kassierer","gender":"m","text":"Gut, das macht 65 Euro. Säule Nummer 4, nicht 2 und nicht 6."},{"speaker":"Kunde","gender":"m","text":"Alles klar, Nummer 4, 65 Euro. Hier ist die Karte, danke."}],"q":"An welcher Säule hat der Kunde getankt?","opts":["Nummer 4.","Nummer 2.","Nummer 6."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, was kostet die Autowäsche heute? 6 Euro, 9 Euro oder 12 Euro?"},{"speaker":"Mitarbeiter","gender":"m","text":"Das einfache Programm kostet 6 Euro. 12 Euro wäre das größte Programm mit Extra-Glanz."},{"speaker":"Kundin","gender":"f","text":"Und mit Wachs? Ist das 9 Euro oder 12 Euro?"},{"speaker":"Mitarbeiter","gender":"m","text":"Mit Wachs 9 Euro. Nicht 6 und nicht 12, mit Wachs sind es 9 Euro."},{"speaker":"Kundin","gender":"f","text":"Dann nehme ich mit Wachs für 9 Euro. Danke."}],"q":"Was kostet die Wäsche mit Wachs?","opts":["6 Euro.","9 Euro.","12 Euro."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Wo kann ich Luft in die Reifen füllen? Kostet das 2 Euro oder 5 Euro?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Hinten links, neben der Waschanlage. 2 Euro oder 5 Euro wäre viel für Luft."},{"speaker":"Mann","gender":"m","text":"Kostet das was? 2 Euro, 5 Euro oder nichts?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Nein, das ist kostenlos. Nicht 2 Euro und nicht 5 Euro, Luft ist umsonst."},{"speaker":"Mann","gender":"m","text":"Super, dann kostenlos. Danke."}],"q":"Was kostet das Füllen der Reifen mit Luft?","opts":["2 Euro.","5 Euro.","Es ist kostenlos."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Kann ich mit Karte zahlen? Auch einen kleinen Betrag, oder erst ab zehn Euro, oder gar nicht?"},{"speaker":"Kassiererin","gender":"f","text":"Ja, natürlich. Auch kleine Beträge gehen mit Karte, Sie müssen nicht bis zehn Euro warten."},{"speaker":"Kunde","gender":"m","text":"Auch einen kleinen Betrag? Ab einem Euro, oder wirklich ab zehn?"},{"speaker":"Kassiererin","gender":"f","text":"Ja, ab einem Euro geht das, nicht erst ab zehn Euro."},{"speaker":"Kunde","gender":"m","text":"Perfekt, dann zahle ich mit Karte. Danke."}],"q":"Ab welchem Betrag kann man mit Karte zahlen?","opts":["Ab einem Euro.","Ab zehn Euro.","Gar nicht."],"correct":0},{"lines":[{"speaker":"Frau","gender":"f","text":"Haben Sie auch Kaffee zum Mitnehmen? Oder nur Getränke, oder nur Süßigkeiten?"},{"speaker":"Verkäufer","gender":"m","text":"Ja, an der Maschine dort. Nicht nur Getränke und nicht nur Süßigkeiten."},{"speaker":"Frau","gender":"f","text":"Und etwas zu essen? Also Kaffee und belegte Brötchen?"},{"speaker":"Verkäufer","gender":"m","text":"Belegte Brötchen liegen in der Vitrine. Kaffee und Brötchen, nicht nur Getränke, nicht nur Süßigkeiten."},{"speaker":"Frau","gender":"f","text":"Dann einen Kaffee und ein Brötchen, bitte. Danke."}],"q":"Was kann die Frau im Shop bekommen?","opts":["Nur Getränke.","Kaffee und belegte Brötchen.","Nur Süßigkeiten."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Pohl, einem Tankstellen-Pächter. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Pohl, verdient man heute noch genug mit dem Verkauf von Benzin?"},{"speaker":"Pohl","gender":"m","text":"Ehrlich gesagt, am Sprit selbst verdienen wir kaum etwas. Das meiste Geld geht an den Staat und die Ölkonzerne. Unser Geld machen wir im Shop — mit Kaffee, Snacks und Zeitungen. Ohne den Shop könnte ich die Tankstelle gar nicht halten. Das wissen die wenigsten Kunden."},{"speaker":"Reporterin","gender":"f","text":"Warum sind die Benzinpreise so unterschiedlich?"},{"speaker":"Pohl","gender":"m","text":"Die ändern sich mehrmals am Tag, das ist verrückt. Morgens ist es oft am teuersten, abends günstiger. Mein Tipp: Tanken Sie nicht morgens, sondern lieber abends. Und vergleichen Sie die Preise mit einer App. Da kann man im Monat richtig Geld sparen, wenn man clever ist."},{"speaker":"Reporterin","gender":"f","text":"Wie wirkt sich das Elektroauto auf Ihr Geschäft aus?"},{"speaker":"Pohl","gender":"m","text":"Das verändert alles. Immer mehr Leute fahren elektrisch und tanken zu Hause. Ich habe schon Ladesäulen aufgestellt, das ist die Zukunft. In zwanzig Jahren wird es kaum noch Benzin geben. Wer sich nicht anpasst, verschwindet. Ich versuche, mit der Zeit zu gehen."},{"speaker":"Reporterin","gender":"f","text":"Sind die langen Öffnungszeiten anstrengend?"},{"speaker":"Pohl","gender":"m","text":"Sehr, wir haben rund um die Uhr offen, auch an Feiertagen. Da arbeitet das Personal in Schichten, auch nachts. Das ist hart, aber die Leute erwarten, dass sie immer tanken können. An Weihnachten zu arbeiten ist nicht schön, aber jemand muss es ja machen. So ist das Geschäft."},{"speaker":"Reporterin","gender":"f","text":"Was wünschen Sie sich von den Kunden?"},{"speaker":"Pohl","gender":"m","text":"Etwas mehr Geduld und Freundlichkeit. Viele sind gestresst und lassen das an uns aus, dabei können wir für die Preise nichts. Ein freundliches Wort kostet nichts und macht den Tag schöner. Wir geben uns Mühe und sind Tag und Nacht für die Menschen da."}],"items":[{"q":"Er rät, am besten morgens zu tanken.","correct":"nein"},{"q":"Herr Pohl verdient das meiste Geld nicht mit Benzin, sondern im Shop.","correct":"ja"},{"q":"Er hat schon Ladesäulen für Elektroautos aufgestellt.","correct":"ja"},{"q":"Seine Tankstelle ist auch nachts und an Feiertagen geöffnet.","correct":"ja"},{"q":"Er wünscht sich weniger Freundlichkeit von den Kunden.","correct":"nein"}]}]};
